  if (input === "") {
    throw new TypeError("invalid money amount");
  }
  const match = /^[-+]?\$?(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(input);
  if (!match) {
    throw new TypeError("invalid money amount");
  }
  const intPart = match[1].replace(/,/g, "");
  const fracPart = match[2] ?? "0";
  const value = Number(`${intPart}.${fracPart}`);
  if (!Number.isFinite(value)) {
    throw new TypeError("invalid money amount");
  }
  const rounded = Math.sign(value) * Math.round(Math.abs(value) * 100) / 100;
  return rounded;
}
