import { parseMoney } from "../src/money.ts";

test("parses dollar and comma-formatted amounts to cents-rounded dollars", () => {
  assert.equal(parseMoney("$12.50"), 12.5);
  assert.equal(parseMoney("12.50"), 12.5);
  assert.equal(parseMoney("0.99"), 0.99);
  assert.equal(parseMoney("1,234.56"), 1234.56);
});

test("rejects empty and non-numeric input", () => {
  assert.throws(() => parseMoney(""), TypeError);
  assert.throws(() => parseMoney("abc"), TypeError);
});
import assert from "node:assert/strict";
import { test } from "node:test";
import { pageSlice } from "../src/pagination.ts";

test("treats page as 1-based", () => {
  assert.deepEqual(pageSlice(["a", "b", "c", "d"], 1, 2), ["a", "b"]);
  assert.deepEqual(pageSlice(["a", "b", "c", "d"], 2, 2), ["c", "d"]);
});

test("rejects a zero or negative page", () => {
  assert.throws(() => pageSlice(["a"], 0, 1), RangeError);
  assert.throws(() => pageSlice(["a"], -1, 1), RangeError);
});
import assert from "node:assert/strict";
import { test } from "node:test";
import { createSku } from "../src/sku.ts";

test("formats a valid department and numeric id", () => {
  assert.equal(createSku("ACC", "0042"), "ACC-0042");
});

test("rejects invalid department or id shapes", () => {
  assert.throws(() => createSku("acc", "0042"), TypeError);
  assert.throws(() => createSku("AC", "0042"), TypeError);
  assert.throws(() => createSku("ACC", "42"), TypeError);
  assert.throws(() => createSku("", "0042"), TypeError);
});
