{"type":"tool_use","timestamp":1787320567035,"sessionID":"ses_fdb651ab6ffe2cbUxCCix28Rqo","part":{"type":"tool","tool":"write","callID":"chatcmpl-tool-ce3d13f2fd6443a38dbf16c52fa25ef9","state":{"status":"completed","input":{"content":"export function parseMoney(input: string): number {
  if (typeof input !== "string" || input.trim() === "") {
    throw new TypeError("invalid money amount");
  }
  const match = input.trim().match(/^\$?-?(\d{1,3}(?:,\d{3})*)(?:\.(\d{1,2}))?$/);
  if (!match) {
    throw new TypeError("invalid money amount");
  }
  const dollars = match[1].replace(/,/g, "");
  const cents = match[2] ?? "00";
  const value = Number(dollars) + Number(cents) / 100;
  if (!Number.isFinite(value)) {
    throw new TypeError("invalid money amount");
  }
  return Math.round(value * 100) / 100;
}
