import assert from "node:assert/strict";
import { test } from "node:test";
import { parseConfig } from "../src/config.ts";

test("parses comments, quotes, and last-wins duplicates", () => {
  const parsed = parseConfig('# heading\nname = ledger\nnote = "hash # ok"\nname = kit\n');
  assert.equal(parsed.name, "kit");
  assert.equal(parsed.note, "hash # ok");
});

test("rejects a line without an equals sign", () => {
  assert.throws(() => parseConfig("broken"), SyntaxError);
});
import assert from "node:assert/strict";
import { test } from "node:test";
import { applyVolumeDiscount } from "../src/discount.ts";

test("applies 5% at 10 items and 10% at 50 items", () => {
  assert.equal(applyVolumeDiscount(100, 9), 100);
  assert.equal(applyVolumeDiscount(100, 10), 95);
  assert.equal(applyVolumeDiscount(100, 50), 90);
});

test("rejects negative inputs", () => {
  assert.throws(() => applyVolumeDiscount(-1, 1), RangeError);
  assert.throws(() => applyVolumeDiscount(10, -1), RangeError);
});
import assert from "node:assert/strict";
import { test } from "node:test";
import { emailKey, formatContact, normalizeEmail } from "../src/email.ts";

test("preserves contact formatting and lookup keys", () => {
  assert.equal(formatContact(" Ada ", "  A@B.C "), "Ada <a@b.c>");
  assert.equal(emailKey("  A@B.C "), "a@b.c");
});

test("exports a shared normalizeEmail helper", () => {
  assert.equal(normalizeEmail("  A@B.C "), "a@b.c");
});
import assert from "node:assert/strict";
import { test } from "node:test";
import { parseMoney } from "../src/money.ts";

test("parses dollar and comma-formatted amounts to cents-rounded dollars", () => {
  assert.equal(parseMoney("$12.50"), 12.5);
  assert.equal(parseMoney("12.50"), 12.5);
  assert.equal(parseMoney("0.99"), 0.99);
  assert.equal(parseMoney("1,234.56"), 1234.56);
});

test("rejects empty and non-numeric input", () => {
  assert.throws(() => parseMoney(""), TypeError);
  assert.throws(() => parseMoney("abc"), TypeError);
});
import assert from "node:assert/strict";
import { test } from "node:test";
import { pageSlice } from "../src/pagination.ts";

test("treats page as 1-based", () => {
  assert.deepEqual(pageSlice(["a", "b", "c", "d"], 1, 2), ["a", "b"]);
  assert.deepEqual(pageSlice(["a", "b", "c", "d"], 2, 2), ["c", "d"]);
});

test("rejects a zero or negative page", () => {
  assert.throws(() => pageSlice(["a"], 0, 1), RangeError);
  assert.throws(() => pageSlice(["a"], -1, 1), RangeError);
