  if (typeof input !== "string" || input.trim() === "") {
    throw new TypeError("invalid money amount");
  }
  const match = input.match(/^\s*\$?\s*([+-]?)(\d{1,3}(?:,\d{3})*)(\.\d{1,2})?\s*$/);
  if (!match) {
    throw new TypeError("invalid money amount");
  }
  const sign = match[1] === "-" ? -1 : 1;
  const integerPart = match[2].replace(/,/g, "");
  const fractionPart = match[3] ? match[3].slice(1) : "";
  const value = sign * (Number(integerPart) + Number(fractionPart) / 100);
  if (!Number.isFinite(value)) {
    throw new TypeError("invalid money amount");
  }
  const scaled = value * 100;
  const rounded = Math.sign(scaled) * Math.floor(Math.abs(scaled) + 0.5);
  return rounded / 100;
}
